DROP POLICY "agency_insert" ON "bonuses" CASCADE;--> statement-breakpoint
DROP POLICY "agency_cancel" ON "bonuses" CASCADE;--> statement-breakpoint
DROP POLICY "agency_insert" ON "pay_adjustments" CASCADE;--> statement-breakpoint
CREATE POLICY "owner_insert" ON "bonuses" AS PERMISSIVE FOR INSERT TO public WITH CHECK (nullif(current_setting('app.team_scope', true), '') = 'owner' and "bonuses"."created_by" = nullif(current_setting('app.user_id', true), '') and not exists (select 1 from team_members m where m.id = "bonuses"."member_id" and m.user_id = nullif(current_setting('app.user_id', true), '')) and "bonuses"."cancelled_at" is null);--> statement-breakpoint
CREATE POLICY "owner_cancel" ON "bonuses" AS PERMISSIVE FOR UPDATE TO public USING (nullif(current_setting('app.team_scope', true), '') = 'owner' and not exists (select 1 from team_members m where m.id = "bonuses"."member_id" and m.user_id = nullif(current_setting('app.user_id', true), '')) and "bonuses"."cancelled_at" is null) WITH CHECK (nullif(current_setting('app.team_scope', true), '') = 'owner' and "bonuses"."cancelled_by" = nullif(current_setting('app.user_id', true), '') and not exists (select 1 from team_members m where m.id = "bonuses"."member_id" and m.user_id = nullif(current_setting('app.user_id', true), '')));--> statement-breakpoint
CREATE POLICY "owner_insert" ON "pay_adjustments" AS PERMISSIVE FOR INSERT TO public WITH CHECK (nullif(current_setting('app.team_scope', true), '') = 'owner' and "pay_adjustments"."created_by" = nullif(current_setting('app.user_id', true), '') and not exists (select 1 from team_members m where m.id = "pay_adjustments"."member_id" and m.user_id = nullif(current_setting('app.user_id', true), '')));